async function main() {
  console.log('Creating curriculum expansion...\n');

  // First, create new topics
  console.log('Creating new topics...');
  for (const topic of newTopics) {
    const { data, error } = await supabase
      .from('topics')
      .insert([topic])
      .select()
      .single();

    if (error) {
      if (error.code === '23505') { // Unique violation
        console.log(`  ⚠️  Topic ${topic.slug} already exists, skipping`);
      } else {
        console.error(`  ❌ Error creating ${topic.slug}:`, error.message);
      }
    } else {
      console.log(`  ✅ Created topic: ${topic.slug}`);
    }
  }

  // Get topic IDs
  const { data: allTopics } = await supabase.from('topics').select('id, slug');
  const topicMap = {};
  allTopics.forEach(t => topicMap[t.slug] = t.id);

  // Create lessons
  console.log('\nCreating new lessons...');
  const lessonIds = [];

  for (const lesson of newLessons) {
    const topic_id = topicMap[lesson.topic_slug];
    if (!topic_id) {
      console.error(`  ❌ Topic not found: ${lesson.topic_slug}`);
      continue;
    }

    // Generate slug from title
    const slug = lesson.title
      .toLowerCase()
      .replace(/[^a-z0-9\s-]/g, '')
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-')
      .substring(0, 50);

    const lessonData = {
      title: lesson.title,
      title_id: lesson.title_id,
      slug,
      topic_id,
      difficulty: lesson.difficulty,
      xp_reward: lesson.xp_reward,
      estimated_minutes: lesson.estimated_minutes,
      summary: lesson.summary,
      summary_id: lesson.summary_id,
      concept_body: lesson.concept_body,
      concept_body_id: lesson.concept_body_id,
      indonesian_example: lesson.indonesian_example,
      is_published: false, // Will be published after review
      lesson_number: lesson.lesson_number,
      jurisdiction: 'ID',
      review_status: 'needs_review',
    };

    const { data, error } = await supabase
      .from('lessons')
      .insert([lessonData])
      .select()
      .single();

    if (error) {
      console.error(`  ❌ Error creating lesson "${lesson.title}":`, error.message);
    } else {
      console.log(`  ✅ Created lesson: ${lesson.title} (#${lesson.lesson_number}) [${slug}]`);
      lessonIds.push({ id: data.id, title: lesson.title, slug, lesson_number: lesson.lesson_number });
    }
  }

  // Generate summary
  console.log('\n=== CURRICULUM EXPANSION COMPLETE ===\n');
  console.log(`New topics created: ${newTopics.length}`);
  console.log(`New lessons created: ${lessonIds.length}`);
  console.log(`\nLesson numbers: ${lessonIds.map(l => l.lesson_number).join(', ')}`);
  console.log(`\nAll lessons are unpublished and marked as "needs_review"`);
  console.log(`\nNext steps:`);
  console.log(`1. Review lesson content in database`);
  console.log(`2. Add sources and content variants`);
  console.log(`3. Publish lessons when ready`);
  console.log(`4. Update Linear and TASKS.md`);

  // Generate SQL migration for reference
  const sqlLines = [
    '-- Curriculum Expansion: 13 New Lessons',
    '-- Date: 2026-07-25',
    '-- This migration was executed via script, not SQL',
    '',
    '-- New topics:',
    ...newTopics.map(t => `-- ${t.slug}: ${t.name}`),
    '',
    '-- New lessons:',
    ...lessonIds.map(l => `-- #${l.lesson_number}: ${l.slug}`),
  ];

  writeFileSync('curriculum-expansion-log.sql', sqlLines.join('\n'));
  console.log('\n✓ Generated curriculum-expansion-log.sql');
}

main().catch(console.error);
